// QA joint plugin-logs acceptance (plugin-admin-surfaces box 4.1, Tier 1):
// the host→api log contract over the FULL production path. A REAL
// cmd/mellifera server subprocess (qaLogsStartServer) whose REAL plugin
// harness (plugin.Manager defaultLaunch → go-plugin magic-cookie handshake +
// gRPC dial, ClientConfig.Stderr = the per-plugin capture ring) launches THIS
// repo's fake plugin subprocess (internal/plugin/testdata/fakeplugin) in the
// tv-parser slot; the subprocess writes a scripted stderr payload in one
// Write before its handshake (MELLIFERA_TEST_STDERR, the fixture's additive
// test knob), and the tail comes back byte-identical, oldest-first, through
// the production chain:
//
//	subprocess stderr → ClientConfig.Stderr (the plugin's log ring)
//	  → Manager.Logs → newPluginLogsClosure (cmd/mellifera) → Deps.PluginLogs
//	  → GET /api/v1/admin/plugins/{plugin_id}/logs (the admin-gated route)
//
// The payload is 300 numbered newline-terminated lines — MORE than the ring's
// 256-line capacity, so the served tail must be the LAST 256 lines in write
// order — with one 3000-byte line among them, MORE than the 2 KiB per-line
// clamp, so the served form must be its first 2048 bytes. The clamp COUNT and
// the tail-drop ORDER are unit-ring territory (TestLogRing); what the joint
// owns is the TRANSPORT of those exact bytes: chunked pipe reads reassembled
// host-side must survive the closure copy and the JSON wire unchanged.
//
// HERMETIC: no library is ever created, so no metadata derivation can run —
// the only traffic is the test's own loopback HTTP and the go-plugin
// handshakes over local sockets. The real shikimori plugin (booted like every
// seeded plugin, all binaries pinned to tmp builds) has its upstream
// resolved once at process start from MELLIFERA_SHIKIMORI_UPSTREAM — pinned
// to a dead loopback port, so even an accidental fetch could not leave the
// machine (and would fail loudly in the captured server log).
//
// The subprocess writes its whole payload BEFORE its handshake, and
// stderr is a FIFO pipe read sequentially by the host copier, so once the
// served tail equals the expected last-256 the capture is provably complete —
// the poll loop's success condition is terminal, never a lucky snapshot.
//
// Every helper is qaLogs-prefixed to stay collision-free in package itest
// (the qaGate/qaSerial conventions).
package itest

import (
	"fmt"
	"net"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"slices"
	"strings"
	"testing"
	"time"
)

// Fixture identity constants (no-coincidence discipline: independent of every
// other qa fixture's literals). The slot is tv-parser — a local filename
// parser no test path invokes (no tv library is ever created), so the fake
// plugin's scanner/metadata RPC surface is never exercised: the joint tests
// the LAUNCH + capture path only, exactly what the logs contract needs.
const (
	qaLogsToken    = "qa-logs-admin-token"
	qaLogsPluginID = "tv-parser" // the boot slot the fake plugin subprocess fills

	// The payload script: 300 numbered lines with the over-clamp line at
	// 0-based slot 149 (line 150 — inside the served tail, not at a boundary).
	qaLogsLineCount  = 300  // > the ring's 256-line capacity → tail-drop semantics
	qaLogsClampIndex = 149  // 0-based slot of the over-clamp line
	qaLogsClampLen   = 3000 // > the 2 KiB line clamp → clamped-byte transport

	// The host-side bounds the served form must respect (internal/plugin
	// logring constants, mirrored here as the EXPECTED wire shape — the unit
	// ring tests own their enforcement).
	qaLogsRingLines = 256
	qaLogsRingClamp = 2 * 1024

	// The fixture's knobs (internal/plugin/testdata/fakeplugin): the
	// handshake pair rides the server env to every plugin subprocess
	// (go-plugin clients append the parent environment); the payload is the
	// exact byte string the fixture writes to its stderr before the handshake.
	qaLogsCookieEnv   = "MELLIFERA_TEST_COOKIE"
	qaLogsCookieValue = "test-secret"
	qaLogsPayloadEnv  = "MELLIFERA_TEST_STDERR"

	// The fake upstream pin: loopback port 9 (discard) has no listener — any
	// accidental fetch dies immediately on loopback, never leaving the machine.
	qaLogsDeadUpstream = "http://127.0.0.1:9"
)

// qaLogsClampLine is the over-clamp line: qaLogsClampLen printable bytes that
// must reach the wire as its first qaLogsRingClamp bytes.
func qaLogsClampLine() string {
	prefix := "qa-logs clamp probe " // 20 bytes
	return prefix + strings.Repeat("A", qaLogsClampLen-len(prefix))
}

// qaLogsPayload builds the scripted stderr payload: qaLogsLineCount newline-
// terminated lines (the over-clamp line one of them — its own line, never
// fused with a neighbor), everything else numbered — the exact bytes the
// fakeplugin subprocess writes to its stderr.
func qaLogsPayload() string {
	var b strings.Builder
	for i := range qaLogsLineCount {
		if i == qaLogsClampIndex {
			b.WriteString(qaLogsClampLine() + "\n")
		} else {
			fmt.Fprintf(&b, "qa-logs stderr line %03d of %d\n", i+1, qaLogsLineCount)
		}
	}
	return b.String()
}

// qaLogsExpectedTail derives the wire shape the joint demands: the payload's
// LAST qaLogsRingLines lines, oldest-first, each line the ring's clamped
// form (the first qaLogsRingClamp bytes of an over-clamp line). Derived
// independently of the server — byte equality against it IS the assertion.
func qaLogsExpectedTail() []string {
	lines := strings.Split(strings.TrimSuffix(qaLogsPayload(), "\n"), "\n")
	tail := slices.Clone(lines[len(lines)-qaLogsRingLines:])
	for i, line := range tail {
		if len(line) > qaLogsRingClamp {
			tail[i] = line[:qaLogsRingClamp]
		}
	}
	return tail
}

// qaLogsStartServer boots the joint's server subprocess: the seven-binary
// boot set with the fakeplugin binary in the tv-parser slot (its payload +
// cookie pair riding the server env to the subprocess — plugin children
// inherit the server env), the other six slots the real pinned tmp builds,
// and the shikimori upstream dead-pinned. Mirrors qaSerialStartServer's
// boot+ready block; a qaLogs helper rather than a signature change to the
// shared one (the extra env is this box's concern alone).
func qaLogsStartServer(t *testing.T, tmp string) qaSerialServer {
	t.Helper()
	addr := net.JoinHostPort("127.0.0.1", freePort(t))
	dataDir := filepath.Join(tmp, "data")
	srv := exec.Command(buildBinary(t, tmp, "qa-logs-server", "./cmd/mellifera"))
	srv.Env = append(os.Environ(),
		"MELLIFERA_DATA_DIR="+dataDir,
		"MELLIFERA_ADMIN_TOKEN="+qaLogsToken,
		"MELLIFERA_BASE_SCANNER="+buildBinary(t, tmp, "qa-logs-basescanner", "./plugins/base-scanner"),
		"MELLIFERA_TV_PARSER="+buildBinary(t, tmp, "qa-logs-fakeplugin", "./internal/plugin/testdata/fakeplugin"),
		"MELLIFERA_IMAGE_ENRICHER="+buildBinary(t, tmp, "qa-logs-imageenricher", "./plugins/image-enricher"),
		"MELLIFERA_SERIAL_SCANNER="+buildBinary(t, tmp, "qa-logs-scanner", "./plugins/serial-scanner"),
		"MELLIFERA_SERIAL_PARSER="+buildBinary(t, tmp, "qa-logs-parser", "./plugins/serial-parser"),
		"MELLIFERA_FRAME_GRABBER="+buildBinary(t, tmp, "qa-logs-grabber", "./plugins/frame-grabber"),
		"MELLIFERA_SHIKIMORI="+shikimoriBin(t, tmp),
		"MELLIFERA_SHIKIMORI_UPSTREAM="+qaLogsDeadUpstream,
		qaLogsCookieEnv+"="+qaLogsCookieValue,
		qaLogsPayloadEnv+"="+qaLogsPayload(),
		"MELLIFERA_LISTEN="+addr,
	)
	var log strings.Builder
	srv.Stdout = &log
	srv.Stderr = &log
	if err := srv.Start(); err != nil {
		t.Fatalf("start server: %v", err)
	}
	baseURL := "http://" + addr
	t.Cleanup(func() { stopServer(t, srv, &log) })
	if !waitForReady(baseURL) {
		t.Fatalf("server not ready at %s within %s; log:\n%s", baseURL, readinessDial, log.String())
	}
	return qaSerialServer{baseURL: baseURL, dataDir: dataDir}
}

// qaLogsTail is the QA-local decode of the logs route's wire shape
// (api.pluginLogsResponse — black box, like every other qa decode).
type qaLogsTail struct {
	PluginID string   `json:"plugin_id"`
	Lines    []string `json:"lines"`
}

// qaLogsFetchTail GETs the production logs route as admin and decodes the
// body, returning the HTTP status (the caller decides what is fatal).
func qaLogsFetchTail(t *testing.T, c *http.Client, baseURL string) (qaLogsTail, int) {
	t.Helper()
	var tail qaLogsTail
	status := doRequest(t, c, http.MethodGet, baseURL+"/api/v1/admin/plugins/"+qaLogsPluginID+"/logs", qaLogsToken, nil, &tail)
	return tail, status
}

// TestPluginLogsJoint is the captured-logs acceptance floor (spec scenario
// 2b3470f315808c4a): the real plugin harness launches a plugin subprocess
// that writes stderr lines, and the served `lines` match the host-captured
// tail oldest-first — the same bytes the manager's ring holds for that
// plugin, through the production closure wiring and the logs route.
func TestPluginLogsJoint(t *testing.T) {
	if testing.Short() {
		t.Skip("QA plugin-logs joint: skips under -short (builds binaries + subprocesses)")
	}

	srv := qaLogsStartServer(t, t.TempDir())
	client := &http.Client{Timeout: httpTimeout}
	want := qaLogsExpectedTail()

	// Poll the production route until the tail is complete. Readiness already
	// implies the subprocess wrote its whole payload (it precedes the
	// handshake, and the server serves only after every plugin Start), and
	// the FIFO pipe + sequential copier make a matching tail terminal — the
	// remaining wait is only the copier's scheduling lag.
	var got qaLogsTail
	deadline := time.Now().Add(10 * time.Second)
	for {
		var status int
		got, status = qaLogsFetchTail(t, client, srv.baseURL)
		if status != http.StatusOK {
			t.Fatalf("GET logs route for %q: HTTP %d, want 200", qaLogsPluginID, status)
		}
		if got.PluginID != qaLogsPluginID {
			t.Fatalf("logs route echoed plugin_id %q, want %q", got.PluginID, qaLogsPluginID)
		}
		if slices.Equal(got.Lines, want) {
			break
		}
		if !time.Now().Before(deadline) {
			t.Fatalf("served tail never matched the captured expectation\nfirst line:  %q\nlast line:   %q\nlines: %d, want %d\nwant first:  %q\nwant last:   %q",
				first(got.Lines), last(got.Lines), len(got.Lines), len(want), first(want), last(want))
		}
		time.Sleep(probeInterval)
	}

	// Byte-identity, asserted element-wise so a failure names the exact line:
	// every served line IS the expected byte string — the numbered lines
	// verbatim, the over-clamp line as its first 2 KiB, order oldest-first.
	for i := range want {
		if got.Lines[i] != want[i] {
			t.Fatalf("served line %d = %q, want %q (byte-identity broken at the transport)", i, got.Lines[i], want[i])
		}
	}
	// The over-clamp line's served form: exactly the clamped bytes, length
	// and content — the clamped BYTES must survive the whole path (ring copy,
	// closure, JSON wire) even though the clamp COUNT is unit-ring territory.
	clampAt := qaLogsClampIndex - (qaLogsLineCount - qaLogsRingLines)
	if len(got.Lines[clampAt]) != qaLogsRingClamp || got.Lines[clampAt] != qaLogsClampLine()[:qaLogsRingClamp] {
		t.Fatalf("over-clamp line served as %d bytes, want the first %d of the %d-byte line",
			len(got.Lines[clampAt]), qaLogsRingClamp, qaLogsClampLen)
	}
}

// first/last are the diagnostic accessors for the mismatch dump (empty-safe).
func first(lines []string) string {
	if len(lines) == 0 {
		return ""
	}
	return lines[0]
}

func last(lines []string) string {
	if len(lines) == 0 {
		return ""
	}
	return lines[len(lines)-1]
}
